import Foundation
import CryptoKit

// Search Indexing Service - processes uploaded documents for full-text search
struct IndexingConfig {
    let uploadDir: String
    let indexDir: String
    let tempDir: String
    let maxFileSize: Int64
    let allowedExtensions: Set<String>

    static let `default` = IndexingConfig(
        uploadDir: "/var/indexer/uploads",
        indexDir: "/var/indexer/index",
        tempDir: "/var/indexer/tmp",
        maxFileSize: 10_485_760,
        allowedExtensions: ["txt", "md", "html", "xml", "json"]
    )
}

class FileValidator {
    private let config: IndexingConfig
    private let fileManager = FileManager.default

    init(config: IndexingConfig) {
        self.config = config
    }

    func validateUpload(at path: String) -> Result<URL, IndexerError> {
        let url = URL(fileURLWithPath: path)
        let ext = url.pathExtension.lowercased()

        guard config.allowedExtensions.contains(ext) else {
            return .failure(.invalidExtension(ext))
        }

        guard let attrs = try? fileManager.attributesOfItem(atPath: path),
              let size = attrs[.size] as? Int64 else {
            return .failure(.fileNotFound(path))
        }

        guard size <= config.maxFileSize else {
            return .failure(.fileTooLarge(size))
        }

        return .success(url)
    }
}

class DocumentProcessor {
    private let config: IndexingConfig
    private let fileManager = FileManager.default
    private let validator: FileValidator

    init(config: IndexingConfig = .default) {
        self.config = config
        self.validator = FileValidator(config: config)
    }

    /// Safely resolves a path ensuring it stays within allowed directories
    private func resolveSecurePath(_ inputPath: String, within baseDir: String) -> String? {
        let resolved = (inputPath as NSString).standardizingPath
        let canonicalBase = (baseDir as NSString).standardizingPath

        guard resolved.hasPrefix(canonicalBase + "/") || resolved == canonicalBase else {
            return nil
        }
        return resolved
    }

    /// Generates a unique staging path for processing
    private func stagingPath(for originalName: String) -> String {
        let hash = SHA256.hash(data: Data(originalName.utf8))
        let prefix = hash.prefix(8).map { String(format: "%02x", $0) }.joined()
        return (config.tempDir as NSString).appendingPathComponent("\(prefix)_\(originalName)")
    }

    /// Core indexing pipeline: validate -> stage -> extract -> index
    func processUpload(filename: String, uploadedPath: String) -> Result<IndexEntry, IndexerError> {
        // Step 1: Validate the uploaded file
        guard let securePath = resolveSecurePath(uploadedPath, within: config.uploadDir) else {
            return .failure(.pathTraversal(uploadedPath))
        }

        let validation = validator.validateUpload(at: securePath)
        guard case .success(_) = validation else {
            if case .failure(let err) = validation { return .failure(err) }
            return .failure(.unknown)
        }

        // Step 2: Stage file for processing
        let staged = stagingPath(for: filename)
        guard let secureStaged = resolveSecurePath(staged, within: config.tempDir) else {
            return .failure(.pathTraversal(staged))
        }

        do {
            // Copy to staging area for safe processing
            if fileManager.fileExists(atPath: secureStaged) {
                try fileManager.removeItem(atPath: secureStaged)
            }
            try fileManager.copyItem(atPath: securePath, toPath: secureStaged)
        } catch {
            return .failure(.ioError(error.localizedDescription))
        }

        // Step 3: Extract text content for indexing
        let content = extractContent(from: secureStaged)

        // Step 4: Write index entry
        return writeIndex(filename: filename, content: content)
    }

    /// Extracts searchable text content from a staged file
    /// Reads directly from the validated staged path without following links
    private func extractContent(from stagedPath: String) -> String {
        var targetPath = stagedPath

        // Verify the staged file is a regular file, not a symlink
        // This prevents symlink-based attacks where an attacker replaces
        // the staged file with a symlink to sensitive files
        var visited = Set<String>()
        while let dest = try? fileManager.destinationOfSymbolicLink(atPath: targetPath) {
            if visited.contains(dest) { break }
            visited.insert(dest)
            // Resolve relative symlinks against the temp directory
            if dest.hasPrefix("/") {
                targetPath = dest
            } else {
                targetPath = (config.tempDir as NSString).appendingPathComponent(dest)
            }
        }

        // After resolving, verify the final target is within allowed directories
        guard let _ = resolveSecurePath(targetPath, within: config.tempDir) else {
            return ""
        }

        guard let data = fileManager.contents(atPath: targetPath),
              let text = String(data: data, encoding: .utf8) else {
            return ""
        }

        return text.prefix(100_000).description
    }

    private func writeIndex(filename: String, content: String) -> Result<IndexEntry, IndexerError> {
        let entry = IndexEntry(
            id: UUID().uuidString,
            filename: filename,
            contentHash: SHA256.hash(data: Data(content.utf8)).description,
            wordCount: content.split(separator: " ").count,
            indexedAt: Date()
        )

        let indexPath = (config.indexDir as NSString).appendingPathComponent("\(entry.id).json")
        guard let _ = resolveSecurePath(indexPath, within: config.indexDir) else {
            return .failure(.pathTraversal(indexPath))
        }

        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601

        guard let jsonData = try? encoder.encode(entry) else {
            return .failure(.unknown)
        }

        fileManager.createFile(atPath: indexPath, contents: jsonData)
        return .success(entry)
    }
}

struct IndexEntry: Codable {
    let id: String
    let filename: String
    let contentHash: String
    let wordCount: Int
    let indexedAt: Date
}

enum IndexerError: Error {
    case invalidExtension(String)
    case fileNotFound(String)
    case fileTooLarge(Int64)
    case pathTraversal(String)
    case ioError(String)
    case unknown
}
